'use client';

import { useIsNarrow } from '@/registry/ndeko/hooks/use-is-narrow';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { InlineSheet } from '@/registry/ndeko/ui/inline-sheet';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { Composer, ReadOnlyNote } from './composer';
import {
  BRAND,
  DECLINED_LINE,
  LIVE_ID,
  LIVE_TITLE,
  NEW_ID,
  NEW_SESSION_TITLE,
  pastSessionOf,
  UNPAID_TOTAL,
  type Attachment,
} from './data';
import {
  INITIAL,
  isBusy,
  isReadOnly,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  sendableTextOf,
  type Decision,
  type WorkspaceState,
} from './session';
import { SessionHeader, statusWordOf } from './session-header';
import { rowsOf, SessionsSidebar } from './sessions-sidebar';
import { Thread } from './thread';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

/** The width of the `@3xl` container variant: under it the sessions live in a sheet. */
const SHEET_BELOW_REM = 48;

function titleOf(state: WorkspaceState) {
  if (state.activeId === LIVE_ID) {
    if (state.turns.length === 0) {
      return NEW_SESSION_TITLE;
    }
    return LIVE_TITLE;
  }
  if (state.activeId === NEW_ID) {
    return NEW_SESSION_TITLE;
  }
  return pastSessionOf(state.activeId).title;
}

function placeholderOf(state: WorkspaceState) {
  const last = state.turns.at(-1);
  if (state.activeId === NEW_ID || !last) {
    return 'Describe the work';
  }
  if (last.stage === 'asking') {
    return 'Allow or deny the request above, or queue a follow-up';
  }
  if (isBusy(state)) {
    return 'Write a follow-up. It waits until the agent is done';
  }
  return 'Ask for something else';
}

function announcementOf(state: WorkspaceState) {
  const last = state.turns.at(-1);
  if (!last) {
    return '';
  }
  if (last.stage === 'asking') {
    return `Operator asks to send ${UNPAID_TOTAL.count} reminders on WhatsApp. Allow or deny it`;
  }
  if (last.stage === 'declined') {
    return DECLINED_LINE;
  }
  if (last.stage === 'done') {
    return 'Operator is done';
  }
  return '';
}

/**
 * Nothing calls a network. A real agent plugs in here: each message a person sends (also one that
 * waits in the queue), and their answer to a request that waits on them.
 */
export type Application06Props = {
  onSend?: (text: string) => void;
  onApprove?: () => void;
  onDeny?: () => void;
};

export default function Application06({
  onSend,
  onApprove,
  onDeny,
}: Application06Props) {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const hasSheet = useIsNarrow(ref, SHEET_BELOW_REM);
  const last = state.turns.at(-1);
  const sendableText = sendableTextOf(state);
  const canSend = sendableText !== null;
  const canReplay = isFinished && !isAutoplaying;
  const isSheetShown = hasSheet && state.isSidebarOpen;
  const message = spokenUnless(isAutoplaying, announcementOf(state));

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  function send() {
    if (sendableText === null) {
      return;
    }
    act({ type: 'sent' });
    onSend?.(sendableText);
  }

  /** The two buttons leave with the request, so the focus goes to what replaces them: the line that says what was decided. */
  function decide(decision: Decision) {
    act({ type: 'decided', decision });
    focusLater('[data-request]');
    if (decision === 'denied') {
      onDeny?.();
      return;
    }
    onApprove?.();
  }

  function openSessions() {
    act({ type: 'sidebar', isOpen: true });
    focusLater('[data-sheet-close="sessions"]');
  }

  function closeSessions() {
    act({ type: 'sidebar', isOpen: false });
    focusLater('[data-sidebar-open]');
  }

  function openSession(id: string) {
    act({ type: 'sessionOpened', id });
    focusLater('[data-composer-field]');
  }

  function startNewSession() {
    act({ type: 'newSession' });
    focusLater('[data-composer-field]');
  }

  const sidebar = {
    rows: rowsOf(state),
    activeId: state.activeId,
    search: state.search,
    onSearch: (text: string) => act({ type: 'searched', text }),
    onOpen: openSession,
    onNewSession: startNewSession,
  };

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-sidebar text-foreground @container min-h-dvh w-full'
      >
        <div className='relative flex h-dvh min-h-[40rem] overflow-hidden'>
          <div inert={isSheetShown} className='flex min-w-0 flex-1 @3xl:p-2'>
            <aside
              aria-label='Sessions'
              className='hidden w-64 shrink-0 pe-2 @3xl:flex'
            >
              {!hasSheet && <SessionsSidebar {...sidebar} />}
            </aside>
            <main className='bg-background @3xl:hairline-ring @3xl:ring-border flex min-w-0 flex-1 flex-col overflow-clip @3xl:rounded-xl @3xl:shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
              <SessionHeader
                title={titleOf(state)}
                turn={last}
                statusWord={statusWordOf(last)}
                costUsd={state.costUsd}
                hasSheet={hasSheet}
                canReplay={canReplay}
                onReplay={restart}
                onOpenSessions={openSessions}
              />
              <Thread
                state={state}
                pressed={pressed}
                isActive={isInView}
                onDecide={decide}
              />
              <div className='mx-auto w-full max-w-2xl shrink-0 px-4 pb-4'>
                {isReadOnly(state) && (
                  <ReadOnlyNote onNewSession={startNewSession} />
                )}
                {!isReadOnly(state) && (
                  <Composer
                    draft={state.draft}
                    placeholder={placeholderOf(state)}
                    canSend={canSend}
                    isBusy={isBusy(state)}
                    attachments={state.attachments}
                    toolIds={state.toolIds}
                    skillIds={state.skillIds}
                    effort={state.effort}
                    queue={state.queue}
                    hint={state.hint}
                    refusals={state.refusals}
                    pressed={pressed}
                    onDraftChange={(text) => act({ type: 'typed', text })}
                    onSend={send}
                    onAttach={(attachments: Attachment[]) =>
                      act({ type: 'attached', attachments })
                    }
                    onDetach={(id) => act({ type: 'detached', id })}
                    onToggleTool={(id) => act({ type: 'toolToggled', id })}
                    onToggleSkill={(id) => act({ type: 'skillToggled', id })}
                    onEffortChange={(effort) =>
                      act({ type: 'effortSet', effort })
                    }
                    onRemoveQueued={(id) => act({ type: 'queueRemoved', id })}
                  />
                )}
              </div>
            </main>
          </div>

          <InlineSheet
            name='sessions'
            label={`${BRAND.name} sessions`}
            closeLabel='Close the sessions'
            side='start'
            isOpen={isSheetShown}
            className='@3xl:hidden'
            panelClassName='bg-sidebar gap-1 p-3'
            onClose={closeSessions}
          >
            {hasSheet && <SessionsSidebar {...sidebar} />}
          </InlineSheet>
          <LiveRegion message={message} />
        </div>
      </div>
    </ClockGate>
  );
}

'use client';

import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';
import { StreamedText } from '@/registry/ndeko/ui/streamed-text';

import { ApprovalCard, requestViewOf } from './approval-card';
import { CallRow } from './call-row';
import { OPERATOR, seedOf, stepSeedOf, type ResultKind } from './data';
import { ResultCard } from './result-cards';
import {
  ANSWER_WORD_MS,
  type Decision,
  type StepRun,
  type Turn,
} from './session';
import { ThinkingRow } from './thinking-row';

export function OperatorTile() {
  const color = seriesColorOf(OPERATOR.series);

  return <MeshTile seed={OPERATOR.name} color={color} size='lg' />;
}

function resultKindOf(run: StepRun): ResultKind | null {
  if (run.status !== 'done') {
    return null;
  }
  return stepSeedOf(run.id).result ?? null;
}

type AgentTurnProps = {
  turn: Turn;
  pressed: string | null;
  isActive: boolean;
  onDecide: (decision: Decision) => void;
};

export function AgentTurn({
  turn,
  pressed,
  isActive,
  onDecide,
}: AgentTurnProps) {
  const seed = seedOf(turn.seedId);
  const requestView = requestViewOf(turn);
  const lastIndex = turn.steps.length - 1;
  const isAnswering = turn.stage === 'answering';
  const hasAnswer = isAnswering || turn.stage === 'done';
  const isCanned = turn.seedId === 'canned';

  return (
    <div className='flex items-start gap-2.5'>
      <OperatorTile />
      <div className='flex min-w-0 flex-1 flex-col gap-3 pt-1'>
        <span className='sr-only'>{OPERATOR.name}</span>
        {seed.thought !== undefined && (
          <ThinkingRow
            text={seed.thought}
            stage={turn.stage}
            effort={turn.effort}
            isActive={isActive}
            startedAt={turn.startedAt}
            thoughtEndedAt={turn.thoughtEndedAt}
          />
        )}
        {turn.steps.length > 0 && (
          <ol aria-label='What the agent did' className='flex flex-col'>
            {turn.steps.map((run, index) => {
              const kind = resultKindOf(run);
              return (
                <CallRow key={run.id} run={run} isLast={index === lastIndex}>
                  {kind && <ResultCard kind={kind} />}
                </CallRow>
              );
            })}
          </ol>
        )}
        {requestView !== 'none' && (
          <ApprovalCard
            view={requestView}
            pressed={pressed}
            onDecide={onDecide}
          />
        )}
        {hasAnswer && isCanned && (
          <p className='text-muted-foreground text-sm leading-relaxed'>
            {seed.answer}
          </p>
        )}
        {hasAnswer && !isCanned && (
          <p className='text-sm leading-relaxed'>
            <StreamedText
              text={seed.answer}
              isStreaming={isAnswering}
              isActive={isActive}
              wordMs={ANSWER_WORD_MS}
            />
          </p>
        )}
      </div>
    </div>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId } from 'react';

import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { CircleXIcon } from '@/registry/ndeko/lib/icons';
import { fadePresence } from '@/registry/ndeko/lib/motion-presets';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Badge } from '@/registry/ndeko/ui/badge';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';
import { Kbd } from '@/registry/ndeko/ui/kbd';
import { Spinner } from '@/registry/ndeko/ui/spinner';
import { Wash } from '@/registry/ndeko/ui/wash';

import {
  DECLINED_LINE,
  REMINDER_PREVIEW,
  REQUEST_RECIPIENTS,
  SENT_LINE,
  UNPAID_TOTAL,
} from './data';
import type { Decision, Turn } from './session';

export type RequestView = 'none' | 'asking' | 'sending' | 'sent' | 'denied';

export function requestViewOf(turn: Turn): RequestView {
  if (turn.stage === 'asking') {
    return 'asking';
  }
  if (turn.decision === 'denied') {
    return 'denied';
  }
  if (turn.decision === 'approved') {
    const run = turn.steps.find((candidate) => candidate.id === 'reminders');
    if (run?.status === 'done') {
      return 'sent';
    }
    return 'sending';
  }
  return 'none';
}

type RequestBodyProps = {
  pressed: string | null;
  onDecide: (decision: Decision) => void;
};

function RequestBody({ pressed, onDecide }: RequestBodyProps) {
  const titleId = useId();
  const keysId = useId();
  const others = UNPAID_TOTAL.count - REQUEST_RECIPIENTS.length;

  function allow() {
    onDecide('approved');
  }

  function deny() {
    onDecide('denied');
  }

  function decideFromKeys(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'Escape') {
      event.preventDefault();
      deny();
      return;
    }
    const isOnCard = event.target === event.currentTarget;
    const isEnter = event.key === 'Enter';
    if (isEnter && isOnCard) {
      event.preventDefault();
      allow();
    }
  }

  return (
    <div
      role='group'
      tabIndex={0}
      aria-labelledby={titleId}
      aria-describedby={keysId}
      onKeyDown={decideFromKeys}
      className='focus-visible:ring-ring/25 relative isolate flex flex-col gap-3 rounded-xl p-3 outline-none focus-visible:ring-[3px] focus-visible:ring-inset'
    >
      <Wash color='var(--warning)' />
      <div className='flex items-center gap-2.5'>
        <BrandTile brand='whatsapp' size='lg' title='WhatsApp' />
        <div className='flex min-w-0 flex-1 flex-col leading-tight'>
          <h2 id={titleId} className='text-sm font-medium'>
            Send {UNPAID_TOTAL.count} reminders on WhatsApp
          </h2>
          <span className='text-muted-foreground truncate text-xs'>
            One message to each customer
          </span>
        </div>
        <Badge variant='warning' className='hidden @md:inline-flex'>
          Waiting on you
        </Badge>
      </div>
      <div className='bg-foreground/[0.04] flex flex-col gap-2 rounded-lg p-2.5 text-xs'>
        <p className='flex items-center gap-1.5'>
          <span className='flex items-center -space-x-1.5'>
            {REQUEST_RECIPIENTS.map((person) => (
              <Avatar
                key={person.name}
                seed={person.name}
                className='ring-card size-5 ring-2'
              />
            ))}
          </span>
          <span className='text-muted-foreground min-w-0 truncate'>
            {REQUEST_RECIPIENTS[0].name}, {REQUEST_RECIPIENTS[1].name} and{' '}
            {others} more
          </span>
        </p>
        <p className='leading-relaxed'>{REMINDER_PREVIEW}</p>
      </div>
      <div className='flex flex-wrap items-center gap-2'>
        <Button
          type='button'
          size='sm'
          onClick={allow}
          className={pressedSolidOf(pressed === 'allow')}
        >
          Allow
          <Kbd className='ms-0.5'>Enter</Kbd>
        </Button>
        <Button type='button' size='sm' variant='outline' onClick={deny}>
          Deny
          <Kbd className='ms-0.5'>Esc</Kbd>
        </Button>
        <span id={keysId} className='sr-only'>
          Enter allows, Escape denies
        </span>
      </div>
    </div>
  );
}

function ResultGlyph({ view }: { view: RequestView }) {
  if (view === 'sending') {
    return <Spinner aria-hidden='true' />;
  }
  if (view === 'denied') {
    return <CircleXIcon className='text-muted-foreground size-4 shrink-0' />;
  }
  return <DrawnCheck tone='success' entrance='draw' />;
}

function resultLineOf(view: RequestView) {
  if (view === 'sending') {
    return `Sending ${UNPAID_TOTAL.count} reminders`;
  }
  if (view === 'denied') {
    return DECLINED_LINE;
  }
  return SENT_LINE;
}

function ResultLine({ view }: { view: RequestView }) {
  return (
    <div className='flex min-h-11 items-start gap-2.5 p-3 text-[13px] leading-5'>
      <Swap swapKey={view} className='mt-px'>
        <ResultGlyph view={view} />
      </Swap>
      <p
        key={view}
        className='min-w-0 transition-opacity duration-300 starting:opacity-0'
      >
        {resultLineOf(view)}
      </p>
    </div>
  );
}

function viewKeyOf(isAsking: boolean) {
  if (isAsking) {
    return 'request';
  }
  return 'result';
}

type ApprovalCardProps = RequestBodyProps & {
  view: RequestView;
};

export function ApprovalCard({ view, pressed, onDecide }: ApprovalCardProps) {
  const fade = fadePresence();
  const isAsking = view === 'asking';

  return (
    <section
      data-request
      tabIndex={-1}
      aria-label='Request to send the reminders'
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] overflow-hidden rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)] transition-opacity duration-300 outline-none starting:opacity-0'
    >
      <AnimatedSize>
        <AnimatePresence initial={false} mode='popLayout'>
          <motion.div key={viewKeyOf(isAsking)} {...fade}>
            {isAsking && <RequestBody pressed={pressed} onDecide={onDecide} />}
            {!isAsking && <ResultLine view={view} />}
          </motion.div>
        </AnimatePresence>
      </AnimatedSize>
    </section>
  );
}

'use client';

import { useId, useState } from 'react';

import { elapsedOf, formatDuration } from '@/registry/ndeko/lib/agent-run';
import {
  ChevronDownIcon,
  MinusIcon,
  WandIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { CallStatusMark } from '@/registry/ndeko/ui/call-status';
import { Fold } from '@/registry/ndeko/ui/chat-motion';
import { LiveDuration } from '@/registry/ndeko/ui/live-duration';

import { stepSeedOf, type StepKind, type StepSeed } from './data';
import type { StepRun, StepStatus } from './session';

const KIND_WORD: Record<StepKind, string> = {
  tool: 'Tool',
  skill: 'Skill',
};

function StepTile({ seed }: { seed: StepSeed }) {
  if (seed.brand) {
    return <BrandTile brand={seed.brand} size='lg' title={seed.product} />;
  }

  return (
    <span
      aria-hidden='true'
      className='keycap-3d text-muted-foreground inline-flex size-7 shrink-0 items-center justify-center rounded-md'
    >
      <WandIcon className='size-3.5' />
    </span>
  );
}

function StepMark({ status }: { status: StepStatus }) {
  if (status === 'skipped') {
    return (
      <span className='inline-flex size-4 shrink-0 items-center justify-center'>
        <MinusIcon className='text-muted-foreground size-4' />
        <span className='sr-only'>Not run</span>
      </span>
    );
  }
  return <CallStatusMark status={status} />;
}

function StepClock({ run }: { run: StepRun }) {
  if (run.status === 'running') {
    return (
      <LiveDuration
        item={run}
        isRunning
        className='text-muted-foreground w-10 shrink-0 text-end text-xs'
      />
    );
  }
  if (run.status === 'done') {
    const elapsed = elapsedOf(run, run.endedAt ?? 0);
    return (
      <span className='text-muted-foreground w-10 shrink-0 text-end text-xs tabular-nums'>
        {formatDuration(elapsed)}
      </span>
    );
  }
  return null;
}

function sublineOf(seed: StepSeed, status: StepStatus) {
  if (status === 'done') {
    return seed.doneSummary;
  }
  if (status === 'skipped') {
    return 'Nothing was sent';
  }
  return seed.detail;
}

function chevronTurnOf(isOpen: boolean) {
  if (isOpen) {
    return 'rotate-180';
  }
  return 'rotate-0';
}

type CallRowProps = {
  run: StepRun;
  isLast: boolean;
  children?: React.ReactNode;
};

export function CallRow({ run, isLast, children }: CallRowProps) {
  const [isOpen, setIsOpen] = useState(false);
  const detailsId = useId();
  const seed = stepSeedOf(run.id);

  function toggle() {
    setIsOpen((current) => !current);
  }

  return (
    <li className='relative flex gap-2.5 pb-3 transition-[opacity,translate] duration-300 ease-(--ease-out-strong) last:pb-0 starting:translate-y-1 starting:opacity-0'>
      {!isLast && (
        <span
          aria-hidden='true'
          className='bg-border absolute start-3.5 top-8 bottom-1 w-px'
        />
      )}
      <StepTile seed={seed} />
      <div className='flex min-w-0 flex-1 flex-col'>
        <button
          type='button'
          aria-expanded={isOpen}
          aria-controls={detailsId}
          onClick={toggle}
          className='hover:bg-foreground/[0.04] focus-visible:ring-ring/25 -mx-1.5 flex cursor-pointer flex-col rounded-md px-1.5 text-start outline-none focus-visible:ring-[3px]'
        >
          <span className='flex h-7 items-center gap-2 text-[13px]'>
            <span className='min-w-0 truncate font-medium'>{seed.title}</span>
            <StepMark status={run.status} />
            <StepClock run={run} />
            <ChevronDownIcon
              className={cn(
                'text-muted-foreground size-3.5 shrink-0 transition-transform duration-200 ease-(--ease-out-strong)',
                chevronTurnOf(isOpen)
              )}
            />
          </span>
          <span className='text-muted-foreground min-h-5 text-xs leading-5'>
            <span className='text-foreground/70'>{KIND_WORD[seed.kind]}</span>
            <span aria-hidden='true'> · </span>
            <span
              key={run.status}
              className='transition-opacity duration-300 starting:opacity-0'
            >
              {sublineOf(seed, run.status)}
            </span>
          </span>
        </button>
        <Fold open={isOpen} id={detailsId}>
          <dl className='bg-foreground/[0.03] dark:bg-foreground/[0.05] mt-1.5 flex flex-col gap-1 rounded-lg p-2.5 font-mono text-xs leading-relaxed'>
            <div className='flex gap-1.5'>
              <dt className='text-muted-foreground shrink-0'>Input</dt>
              <dd className='min-w-0 break-words'>{seed.input}</dd>
            </div>
            <div className='flex gap-1.5'>
              <dt className='text-muted-foreground shrink-0'>Result</dt>
              <dd className='min-w-0 break-words'>{seed.output}</dd>
            </div>
          </dl>
        </Fold>
        {children}
      </div>
    </li>
  );
}

'use client';

import {
  FileTextIcon,
  ImageIcon,
  WandIcon,
  XIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';

import {
  skillOf,
  toolOf,
  type Attachment,
  type SkillId,
  type ToolId,
} from './data';

const KILOBYTE = 1024;

const MEGABYTE = KILOBYTE * KILOBYTE;

/** 48 KB, 1.2 MB. */
export function formatBytes(bytes: number) {
  if (bytes < MEGABYTE) {
    const rounded = Math.round(bytes / KILOBYTE);
    const kilobytes = Math.max(1, rounded);
    return `${kilobytes} KB`;
  }
  const megabytes = bytes / MEGABYTE;
  return `${megabytes.toFixed(1)} MB`;
}

const CHIP =
  'bg-foreground/[0.05] flex h-7 max-w-full items-center gap-1.5 rounded-lg ps-1.5 pe-1 text-xs transition-[opacity,scale] duration-200 ease-(--ease-out-strong) starting:scale-95 starting:opacity-0';

const REMOVE =
  'text-muted-foreground hover:bg-foreground/[0.07] hover:text-foreground focus-visible:ring-ring/25 flex size-5 shrink-0 cursor-pointer items-center justify-center rounded-md outline-none focus-visible:ring-[3px] active:scale-[0.97]';

type RemoveProps = {
