import { EFFORT_WORD, type Effort } from './data';
import { WORD_MS, type TurnStage } from './session';

function headlineOf(isThinking: boolean, duration: string, effort: Effort) {
  if (isThinking) {
    return 'Thinking';
  }
  const word = EFFORT_WORD[effort].toLowerCase();
  return `Thought for ${duration}, ${word} effort`;
}

function chevronTurnOf(isOpen: boolean) {
  if (isOpen) {
    return 'rotate-180';
  }
  return 'rotate-0';
}

type ThinkingRowProps = {
  text: string;
  stage: TurnStage;
  effort: Effort;
  isActive: boolean;
  startedAt: number;
  thoughtEndedAt?: number;
};

export function ThinkingRow({
  text,
  stage,
  effort,
  isActive,
  startedAt,
  thoughtEndedAt,
}: ThinkingRowProps) {
  const [openChoice, setOpenChoice] = useState<boolean | null>(null);
  const [wasThinking, setWasThinking] = useState(stage === 'thinking');
  const panelId = useId();
  const isThinking = stage === 'thinking';
  const span = { startedAt, endedAt: thoughtEndedAt };
  const elapsed = elapsedOf(span, thoughtEndedAt ?? 0);
  const duration = formatDuration(elapsed);
  const headline = headlineOf(isThinking, duration, effort);

  if (wasThinking !== isThinking) {
    setWasThinking(isThinking);
    setOpenChoice(null);
  }

  const isOpen = openChoice ?? isThinking;

  function toggle() {
    setOpenChoice(!isOpen);
  }

  return (
    <div className='bg-foreground/[0.03] dark:bg-foreground/[0.05] rounded-xl p-1.5'>
      <button
        type='button'
        aria-expanded={isOpen}
        aria-controls={panelId}
        onClick={toggle}
        className='hover:bg-foreground/[0.04] focus-visible:ring-ring/25 flex h-8 w-full cursor-pointer items-center gap-2 rounded-lg px-2 text-start text-[13px] outline-none focus-visible:ring-[3px]'
      >
        <BrainIcon className='text-muted-foreground size-4 shrink-0' />
        <span className='min-w-0 truncate font-medium'>
          <WordRoll text={headline} />
        </span>
        {isThinking && (
          <LiveDuration
            item={span}
            isRunning
            className='text-muted-foreground w-10 text-xs'
          />
        )}
        <ChevronDownIcon
          className={cn(
            'text-muted-foreground ms-auto size-3.5 shrink-0 transition-transform duration-200 ease-(--ease-out-strong)',
            chevronTurnOf(isOpen)
          )}
        />
      </button>
      <Fold open={isOpen} id={panelId}>
        <p className='text-muted-foreground px-2 pt-1.5 pb-2 text-[13px] leading-relaxed'>
          <StreamedText
            text={text}
            isStreaming={isThinking}
            isActive={isActive}
            wordMs={WORD_MS}
          />
        </p>
      </Fold>
    </div>
  );
}

'use client';

import { useFollowBottom } from '@/registry/ndeko/hooks/use-follow-bottom';

import { AgentTurn, OperatorTile } from './agent-turn';
import { AttachmentChip } from './chips';
import {
  EFFORT_WORD,
  FOLLOW_UP_REPLY,
  LIVE_ID,
  NEW_ID,
  pastSessionOf,
  skillOf,
  toolOf,
} from './data';
import type { Decision, Turn, WorkspaceState } from './session';

function PersonBubble({ text }: { text: string }) {
  return (
    <p className='bg-foreground/[0.06] max-w-[85%] self-end rounded-2xl rounded-ee-md px-3.5 py-2 text-sm leading-relaxed'>
      {text}
    </p>
  );
}

function settingsLineOf(turn: Turn) {
  const effort = `${EFFORT_WORD[turn.effort]} effort`;
  const tools = turn.toolIds.map((id) => toolOf(id).name);
  const skills = turn.skillIds.map((id) => skillOf(id).name);
  return [effort, ...tools, ...skills].join(', ');
}

function PersonMessage({ turn }: { turn: Turn }) {
  const hasFiles = turn.attachments.length > 0;

  return (
    <div className='flex max-w-[85%] flex-col items-end gap-1.5 self-end'>
      {hasFiles && (
        <ul
          aria-label='Sent with this message'
          className='flex flex-wrap justify-end gap-1.5'
        >
          {turn.attachments.map((attachment) => (
            <AttachmentChip key={attachment.id} attachment={attachment} />
          ))}
        </ul>
      )}
      <p className='bg-foreground/[0.06] rounded-2xl rounded-ee-md px-3.5 py-2 text-sm leading-relaxed'>
        {turn.text}
      </p>
      <p className='text-muted-foreground text-end text-xs'>
        {settingsLineOf(turn)}
      </p>
    </div>
  );
}

function CannedReply({ text }: { text: string }) {
  return (
    <>
      <PersonBubble text={text} />
      <div className='flex items-start gap-2.5'>
        <OperatorTile />
        <p className='text-muted-foreground min-w-0 flex-1 pt-1 text-sm leading-relaxed'>
          {FOLLOW_UP_REPLY}
        </p>
      </div>
    </>
  );
}

function EmptySession() {
  return (
    <div className='m-auto flex w-full max-w-sm flex-col items-center gap-1.5 py-6 text-center'>
      <h2 className='text-base font-semibold text-balance'>
        Describe the work
      </h2>
      <p className='text-muted-foreground text-[13px] leading-relaxed text-balance'>
        Attach a photo or a file, switch on the tools it may use and set how
        hard it thinks. Each step shows here as it happens.
      </p>
    </div>
  );
}

function PastSummary({ id }: { id: string }) {
  const session = pastSessionOf(id);

  return (
    <>
      <PersonBubble text={session.prompt} />
      <div className='flex items-start gap-2.5'>
        <OperatorTile />
        <div className='flex min-w-0 flex-1 flex-col gap-2 pt-1'>
          <p className='text-sm leading-relaxed'>{session.summary}</p>
          <p className='text-muted-foreground text-xs'>
            A summary of an earlier session. It cannot be continued here.
          </p>
        </div>
      </div>
    </>
  );
}

type TurnViewProps = {
  turn: Turn;
  pressed: string | null;
  isActive: boolean;
  onDecide: (decision: Decision) => void;
};

function TurnView({ turn, pressed, isActive, onDecide }: TurnViewProps) {
  return (
    <>
      <PersonMessage turn={turn} />
      <AgentTurn
        turn={turn}
        pressed={pressed}
        isActive={isActive}
        onDecide={onDecide}
      />
    </>
  );
}

type ThreadProps = {
  state: WorkspaceState;
  pressed: string | null;
  isActive: boolean;
  onDecide: (decision: Decision) => void;
};

export function Thread({ state, pressed, isActive, onDecide }: ThreadProps) {
  const { scrollerRef, contentRef, updatePinned } = useFollowBottom();
  const { activeId, turns, newLines } = state;
  const isLive = activeId === LIVE_ID;
  const isNew = activeId === NEW_ID;
  const isPast = !isLive && !isNew;
  const hasTurns = turns.length > 0;
  const hasNewLines = newLines.length > 0;

  return (
    <div
      ref={scrollerRef}
      onScroll={updatePinned}
      className='min-h-0 flex-1 overflow-y-auto'
    >
      <div
        ref={contentRef}
        className='mx-auto flex min-h-full w-full max-w-2xl flex-col gap-5 px-4 py-5'
      >
        {isLive && !hasTurns && <EmptySession />}
        {isLive &&
          turns.map((turn) => (
            <TurnView
              key={turn.id}
              turn={turn}
              pressed={pressed}
              isActive={isActive}
              onDecide={onDecide}
            />
          ))}
        {isNew && !hasNewLines && <EmptySession />}
        {isNew &&
          newLines.map((text, index) => (
            <CannedReply key={index} text={text} />
          ))}
        {isPast && <PastSummary id={activeId} />}
      </div>
    </div>
  );
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { PlugIcon, WandIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuGroupLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';

import { SKILLS, TOOLS, type SkillId, type ToolId } from './data';

type ToolsMenuProps = {
  toolIds: ToolId[];
  skillIds: SkillId[];
  isPressed: boolean;
  onToggleTool: (id: ToolId) => void;
  onToggleSkill: (id: SkillId) => void;
};

/** The menu belongs to a person. The demonstration switches the tools on, and their chips arrive in the composer. */
export function ToolsMenu({
  toolIds,
  skillIds,
  isPressed,
  onToggleTool,
  onToggleSkill,
}: ToolsMenuProps) {
  const count = toolIds.length + skillIds.length;
  const hasCount = count > 0;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            type='button'
            variant='ghost'
            size='sm'
            aria-label={`Tools and skills, ${count} on`}
            className={cn(
              'text-muted-foreground gap-1.5 px-2',
              pressedQuietOf(isPressed)
            )}
          />
        }
      >
        <PlugIcon />
        <span className='sr-only @md:not-sr-only'>Tools</span>
        {hasCount && (
          <span className='bg-primary/10 text-primary-ink inline-flex h-4 min-w-4 items-center justify-center rounded-full px-1 text-[10px] leading-none font-medium'>
            <MotionNumber value={count} />
          </span>
        )}
      </DropdownMenuTrigger>
      <DropdownMenuContent side='top' align='start' className='w-64'>
        <DropdownMenuGroup>
          <DropdownMenuGroupLabel>Tools</DropdownMenuGroupLabel>
          {TOOLS.map((tool) => (
            <DropdownMenuCheckboxItem
              key={tool.id}
              checked={toolIds.includes(tool.id)}
              onCheckedChange={() => onToggleTool(tool.id)}
            >
              <BrandTile brand={tool.brand} size='sm' />
              {tool.name}
            </DropdownMenuCheckboxItem>
          ))}
        </DropdownMenuGroup>
        <DropdownMenuSeparator />
        <DropdownMenuGroup>
          <DropdownMenuGroupLabel>Skills</DropdownMenuGroupLabel>
          {SKILLS.map((skill) => (
            <DropdownMenuCheckboxItem
              key={skill.id}
              checked={skillIds.includes(skill.id)}
              onCheckedChange={() => onToggleSkill(skill.id)}
              className='h-auto items-start py-1.5'
            >
              <WandIcon className='mt-0.5' />
              <span className='flex min-w-0 flex-col'>
                <span>{skill.name}</span>
                <span className='text-muted-foreground text-xs'>
                  {skill.hint}
                </span>
              </span>
            </DropdownMenuCheckboxItem>
          ))}
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
